def _ctrace(event: str, **fields) -> None:
    """通话追踪埋点（诊断专用；未开启时立即返回，见 src/llm/call_trace.py）。"""
    try:
        from ..llm.call_trace import trace as _t
        _t(event, **fields)
    except Exception:  # noqa: BLE001
        pass


