    # 故音频起点可比文本起点早若干秒；原硬编码 1.0 ⇒ 误杀（详见 _flush_duplex_emit）。
    _DUPLEX_AUDIO_LOOKBACK_S = 8.0
    _COMM_PEAK = _COMM_PEAK
