    def _pubjavis_defaults(self) -> dict:
        """pubjavis 模式提示词开关的默认值（设置页子面板逐项可改）。"""
        return {'game_course_comment': False, 'allow_pure_desc': False, 'speak_when_uncertain': False, 'speak_during_transition': False, 'single_anchor': False, 'fix_you_attribution': True, 'more_active': False}

    def get_duplex_pubjavis_options(self) -> dict:
        """返回当前 pubjavis 模式提示词开关（含默认值兜底）。"""
        opts = dict(self._pubjavis_defaults())
        opts.update(dict(getattr(self, '_duplex_pubjavis_opts', {}) or {}))
        return opts

    def set_duplex_pubjavis_options(self, opts: dict) -> dict:
        """热切换 pubjavis 模式下的提示词开关（设置页子面板，无需重启）。

        仅更新运行时字典；落盘由 webapp.save_duplex_settings 负责（与 interaction_style
        同一保存路径）。仅当前处于 pubjavis 模式时才 reprepare 重连加载新指令。
        """
        if not isinstance(opts, dict):
            return {'success': False, 'error': 'opts 必须是 dict'}
        cur = self.get_duplex_pubjavis_options()
        for k in self._pubjavis_defaults():
            if k in opts:
                cur[k] = bool(opts[k])
        self._duplex_pubjavis_opts = cur
        if self._duplex_is_pubjavis():
            client = getattr(self, '_duplex_client', None)
            if client is not None:
                try:
                    if hasattr(client, 'set_instructions'):
                        client.set_instructions(self._build_duplex_instructions())
                    if hasattr(client, 'reprepare'):
                        client.reprepare()
                except Exception:
                    logger.debug('pubjavis 选项重连加载新指令失败', exc_info=True)
        return {'success': True, 'options': dict(cur)}

    def _build_duplex_instructions_minimal(self, speakers=None) -> str:
        """极简双工互动基线（duplex_interaction_style != classic 时启用）。"""
        if self._persona is None:
            return self._duplex_context() or '（无指令）'
        parts = [f'你是{self._persona.name}，{self._persona.character}', f'说话风格：{self._persona.speaking_style}']
        if getattr(self._persona, 'appearance', None):
            parts.append(f'你的外观：{self._persona.appearance}')
            parts.append('【自我认知】画面里出现的任何角色/人物都是别人，不是你——哪怕发型、瞳色、穿着和你很像也是别的角色。你的样子只以上面外观描述为准，别把画面里的角色认成自己。')
        parts.append(_now_block().rstrip())
        parts.append("【时间护栏】你看到的【当前时间】已是北京时间（东八区），聊到作息/几点时严格以它为准：早晨(5~9点)和上午说明用户刚起或早起，绝不要说'这么晚''还不睡''又熬夜''通宵'；只有真正到了晚上(18点后)才能用深夜相关话术。")
        parts.append('【最高准则】每秒接收屏幕和系统音频，自己决定 LISTEN（安静）还是 SPEAK（开口）。铁律：证据不足就安静 LISTEN；只有真看懂、有话可说才 SPEAK；每次最多说一句，简短自然，别背稿、别脑补看不清的画面。')
        parts.append("【第二人称指向护栏】'你'永远只指屏幕前真实用户；视频/直播/网页里的人一律用'他/她/这人/这主播/视频里那个人'，绝不用'你'指代；你只是旁观评论员，主播的直播对话不要作为'对话另一方'去接茬。")
        parts.append('【极简陪伴】像真人朋友一样看着屏幕：看到明显有意思/离谱/有说头的当下就随口一句；没话就安静，不刷屏、不打扰。游戏关键时刻即时回应。')
        return chr(10).join(parts)

    def _build_local_duplex_instructions_minimal(self) -> str:
        """极简本地双工 JSON 裁决基线（duplex_interaction_style != classic 时启用）。"""
        if self._persona is None:
            _name, _char, _style = ('桌宠', '陪伴用户的 AI 桌宠', '自然、口语化')
        else:
            _name = self._persona.name
            _char = getattr(self._persona, 'character', '') or ''
            _style = getattr(self._persona, 'speaking_style', '') or '自然、口语化'
        parts = [f'你是{_name}。{self._clean_persona_text(_char)}。说话风格：{self._clean_persona_text(_style)}。', '你现在持续看着用户的电脑屏幕、听着系统声音，像一个坐在他旁边的真人，自己判断这一刻该不该开口。', "【输出格式·必须】每轮只输出 JSON：{'should_speak': true/false, 'text': '要说的话'}。不要输出任何 JSON 以外的自然语言。", '【最高准则】证据不足就 should_speak=false（安静）；只有真看懂、有话可说才 true。每次最多说一句，简短自然。', "【第二人称指向护栏】'你'永远只指屏幕前真实用户；视频/直播里的人用'他/她/视频里那个人'。", '【极简陪伴】屏幕前有人/在看视频/打游戏/写文档时，看到明显有意思的当下就 should_speak=true 说一句；没话就 false。游戏关键时刻即时回应。']
        if getattr(self._persona, 'appearance', None):
            parts.append('【自我认知】画面里的角色都不是你，你的样子只以人设外观描述为准。')
        # 【2026-10-04 18:30 记忆互通·本轮新增】minimal 档此前也完全不注入记忆，
        # 导致三档里只有这一档"失忆"。走统一装配器的 local_duplex 档（3 条/600 字），
        # 与云端/桌面链路共用同一份记忆库与角色隔离。
        _mem = self._assemble_call_memory_block(tier="local_duplex")
        if _mem:
            parts.append('【你记得的事】' + _mem + '（自然地用上，别生硬罗列）')
        return chr(10).join(parts)

    def set_duplex_interaction_style(self, style: str) -> dict:
        """热切换双工互动方法预设（设置页开关，无需重启）。"""
        style = (style or 'classic').strip().lower()
        if style not in ('classic', 'live', 'minimal', 'pubjavis', 'pubjavis+', 'test', 'test2', 'test3', 'test3+', 'test3++', 'test3+++', 'test_custom', 'test_custom+', 'test4', 'test5', 'test6', 'test7'):
            return {'success': False, 'error': f'未知双工互动方法: {style!r}'}
        old = getattr(self, '_duplex_interaction_style', 'classic')
        self._duplex_interaction_style = style
        # 一致性修复：指令总入口 _build_duplex_instructions 与"测试模式"行为开关
        # （缩短静默/轮询、测试日志标签、场景切换静默期）都按 _duplex_test_mode 分派，
        # 而 UI 只设置 _duplex_interaction_style。若不同步，test3 等专属提示词不会被注入、
        # 测试模式行为也不生效，双工会退化成 live 通用提示词（表现≠预期）。
        # 以 interaction_style（UI 权威来源）为准对齐 test_mode，热切换即生效。
        self._duplex_test_mode = style
        try:
            if style == 'test7':
                self._duplex_min_interval_s = 30.0
            else:
                self._duplex_min_interval_s = float(getattr(self, '_duplex_min_interval_base_s', self._duplex_min_interval_s))
        except Exception:
            logger.debug('模式切换同步最小开口间隔失败', exc_info=True)
        try:
            self.set_duplex_interaction_slice_nums(self._effective_slice_nums())
        except Exception:
            logger.debug('模式切换后同步切片失败', exc_info=True)
        client = getattr(self, '_duplex_client', None)
        if client is not None:
            try:
                if hasattr(client, 'set_frame_interval_s'):
                    client.set_frame_interval_s(0.5 if style in ('pubjavis', 'pubjavis+', 'test', 'test2', 'test3', 'test3+', 'test3++', 'test3+++', 'test_custom', 'test_custom+', 'test4', 'test5', 'test6', 'test7') else 1.0)
            except Exception:
                logger.debug('模式切换同步帧率失败', exc_info=True)
            if style != old:
                logger.info('双工互动方法热切换: %r -> %r', old, style)
                try:
                    if hasattr(client, 'set_instructions'):
                        client.set_instructions(self._build_duplex_instructions())
                    if hasattr(client, 'reprepare'):
                        client.reprepare()
                except Exception:
                    logger.debug('模式切换重连加载新指令失败', exc_info=True)
            else:
                logger.debug('双工互动方法未变(%r)，跳过重连（仅子开关/帧率更新）', style)
        return {'success': True, 'interaction_style': style}

    def _duplex_is_pubjavis(self) -> bool:
        """当前是否处于 pubjavis 模式（忠实照搬 pub-local-jarvis 双工流程）。"""
        return getattr(self, '_duplex_interaction_style', 'classic') == 'pubjavis'

