        # 「会话已建·模型载入中」的 prepared，约 20s 后才发真正就绪的 prepared。
        # ready 只认后者（见 _on_duplex_status），否则拨号页会提前"接通"。
        self._duplex_call_model_loading = False
        # 状态文案（人类可读）：dict 状态取 msg 字段，避免拨号页把 dict repr 原样显示。
        self._duplex_status_text = ""
        self._duplex_call_start_epoch = 0.0
        self._duplex_capture_audio = False
        self._duplex_client = None
        self._duplex_emit_buf = None
        self._duplex_emit_timer = None
        # 【2026-10-11·聊天页主动修复】本段出声的"去向"意图：True=落聊天页（聊天页空闲
        #   主动/长会话收尾/记忆型主动），False=落桌宠 Live2D 气泡（双工看屏/系统兜底）。
        #   与 _duplex_emit_buf 同生命周期：_schedule_duplex_emit 起段时置位、_flush 取用后复位。
        self._duplex_emit_to_chat = False
        # 【2026-09-12 接线原生克隆】模型原生语音缓冲（float32@24k 原始字节 + 最近到达时间）。
        # 旧链路：on_speak 收到 audio_pcm 就丢（从未装进 AI_DECISION），本地 omni 服务端
        # 声码器白跑。现在随文本攒入、出声时挂 payload['audio_pcm']，tts 见到即直接播。
        # 过期保护：文本被质量门拦掉时音频会滞留缓冲，>10s 未出声则弃（防串到下一句）。
        self._duplex_emit_audio = bytearray()
        self._duplex_emit_audio_ts = 0.0
        # 本段原生语音的【起始】时间戳（区别于 _duplex_emit_audio_ts 的“最近一片”）。
        # 串音守卫必须看起点：只看最后一片到达时间，会让上一轮残留音频
        # 被新一片刷新成“新鲜”，从而绕过守卫跟着下一句一起播。
        self._duplex_emit_audio_start_ts = 0.0
        self._DUPLEX_AUDIO_MAX_AGE_S = 10.0
        # 本次出声缓冲的起始时间：只有**晚于它**到达的原生语音才配得上这句话
        # （早到的属于被质量门拦掉的上一次开口，必须排除，否则会串音）。
        self._duplex_emit_start_ts = 0.0
        self._duplex_endpoint = None
        self._duplex_force_active = False
        self._duplex_foreground = None
        self._duplex_frag_buf = ''
        self._duplex_frag_ts = 0.0
        self._duplex_free_rounds = 0
        self._duplex_hist_frame_inject = False
        # 通话(mic 源)是否仍套“防自听”闸门（见 local_omni_duplex._mic_gate 注释）。
        # False=不拦截 → 她出声期间用户也能插话；默认 False。
        self._duplex_mic_gate = False
